import{c as t,Q as n,j as a,m as r}from"./chunks/framework.BqPkuuVc.js";const p=JSON.parse('{"title":"Troubleshooting","description":"","frontmatter":{},"headers":[],"relativePath":"user/reference/troubleshooting.md","filePath":"user/reference/troubleshooting.md"}'),o={name:"user/reference/troubleshooting.md"};function s(i,e,h,d,l,c){return n(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h1><p><strong>Audience:</strong> Anyone hitting an error or unexpected behaviour in Manager.</p><p>Symptoms, likely causes, and fixes, grouped by when you&#39;ll meet them. For a result that looks wrong, start with <a href="./../running-the-event/resolving-issues">Resolving issues on the day</a> instead.</p><h2 id="starting-manager" tabindex="-1">Starting Manager <a class="header-anchor" href="#starting-manager" aria-label="Permalink to &quot;Starting Manager&quot;">​</a></h2><h3 id="macos-says-mesho-manager-is-damaged-and-can-t-be-opened" tabindex="-1">macOS says meshO Manager &quot;is damaged and can&#39;t be opened&quot; <a class="header-anchor" href="#macos-says-mesho-manager-is-damaged-and-can-t-be-opened" aria-label="Permalink to &quot;macOS says meshO Manager &quot;is damaged and can&#39;t be opened&quot;&quot;">​</a></h3><p><strong>The app is not damaged.</strong> macOS shows this (or &quot;…can&#39;t be opened because it is from an unidentified developer&quot;) the first time you launch Manager because it isn&#39;t notarised by Apple yet and your browser tagged the download with a quarantine flag. <strong>Don&#39;t move it to the Bin.</strong> Open <strong>Terminal</strong> and run:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">xattr</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -cr</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /Applications/meshO</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\ </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Manager.app</span></span></code></pre></div><p>Then launch Manager normally from Applications. This is a one-time step. It is not caused by the browser you used (Safari, Chrome and Edge all behave the same), nor by whether your Mac is Intel or Apple Silicon, and the &quot;damaged&quot; message is <em>not</em> cleared by right-click → Open — only the Terminal command above works. Full details, including the path for the milder &quot;unidentified developer&quot; message, are in <a href="./../download-and-install/#allowing-the-app-on-macos">Allowing the app on macOS</a>.</p><h3 id="manager-doesn-t-open-or-keeps-stopping" tabindex="-1">Manager doesn&#39;t open, or keeps stopping <a class="header-anchor" href="#manager-doesn-t-open-or-keeps-stopping" aria-label="Permalink to &quot;Manager doesn&#39;t open, or keeps stopping&quot;">​</a></h3><p>Manager runs as a server in the background with a small tray (Windows) or menu bar (macOS) icon; the browser tab is only a window onto it. So:</p><ul><li><strong>Nothing opens when you launch it.</strong> Look for the meshO icon in the tray or menu bar. If it&#39;s there, click it and choose <strong>Open</strong>. Closing the browser tab doesn&#39;t stop Manager, so it may already be running.</li><li><strong>The menu says <em>Server stopped: it kept stopping unexpectedly</em>.</strong> The server stopped six times in ten minutes, so Manager stopped restarting it. The commonest cause is another program using Manager&#39;s port (<code>5154</code>, or whatever <strong>Settings → Server</strong> says). Close that program, or change the port, then choose <strong>Start Server</strong> from the menu. An alert also explains what went wrong.</li><li><strong>You ended Manager in Task Manager or Activity Monitor, and it came straight back.</strong> That looks like a crash, so Manager restarts itself. Use <strong>Quit</strong> from the tray or menu bar instead.</li></ul><p>See <a href="./../download-and-install/#how-the-server-runs-in-the-background">How the server runs in the background</a>.</p><h3 id="other-devices-can-t-reach-manager-at-all" tabindex="-1">Other devices can&#39;t reach Manager at all <a class="header-anchor" href="#other-devices-can-t-reach-manager-at-all" aria-label="Permalink to &quot;Other devices can&#39;t reach Manager at all&quot;">​</a></h3><p>If neither the name link nor the IP link opens from any other device, check that <strong>Allow access from other devices on the network</strong> is on in <strong>Settings → Server</strong>. Then check the server computer&#39;s firewall: on Windows, the first launch asks to allow Manager on <strong>Private networks</strong>, and answering no blocks every other device. See <a href="./../download-and-install/#firewall-prompt-on-first-launch">Firewall prompt on first launch</a>.</p><h2 id="connecting-hardware" tabindex="-1">Connecting hardware <a class="header-anchor" href="#connecting-hardware" aria-label="Permalink to &quot;Connecting hardware&quot;">​</a></h2><h3 id="the-sportident-station-doesn-t-appear-in-the-browser-s-device-chooser-macos" tabindex="-1">The SportIdent station doesn&#39;t appear in the browser&#39;s device chooser (macOS) <a class="header-anchor" href="#the-sportident-station-doesn-t-appear-in-the-browser-s-device-chooser-macos" aria-label="Permalink to &quot;The SportIdent station doesn&#39;t appear in the browser&#39;s device chooser (macOS)&quot;">​</a></h3><p>On a Mac, the browser&#39;s serial-device chooser comes up <strong>empty</strong> (or lists only unrelated ports) even though the station is plugged in and powered. macOS doesn&#39;t recognise SportIdent&#39;s USB product ID, so it never creates a serial port for the station — and Web Serial can only offer up real ports. Install the Silicon Labs CP210x driver once per Mac, and approve it in <strong>System Settings</strong> (the installer stalls at &quot;Installing new driver…&quot; until you do). Full steps: <a href="./sportident-usb-on-macos">SportIdent USB stations on macOS</a>.</p><p>If the chooser <em>does</em> list the station but the download controls never appear at all, that&#39;s a different problem — Web Serial needs a secure connection off the server machine. See <a href="./https-and-certificates">HTTPS and certificates</a>.</p><h3 id="a-usb-printer-on-a-windows-laptop-won-t-print-from-the-browser" tabindex="-1">A USB printer on a Windows laptop won&#39;t print from the browser <a class="header-anchor" href="#a-usb-printer-on-a-windows-laptop-won-t-print-from-the-browser" aria-label="Permalink to &quot;A USB printer on a Windows laptop won&#39;t print from the browser&quot;">​</a></h3><p><strong>Test print</strong> says <em>Windows has its own driver on this USB printer, so the browser cannot use it</em> — or, in older versions, <em>Windows is using this printer through its own driver</em>, or even <em>A USB printer needs the secure (https://) link</em> on a page that is already https. Windows attaches its own driver (<strong>USB Printing Support</strong>) to nearly every USB printer, and the browser can only open one whose driver is <strong>WinUSB</strong>. Removing the printer from <strong>Printers &amp; scanners</strong> doesn&#39;t change that driver. Switch it to WinUSB with Zadig, once per laptop. Full steps: <a href="./usb-printer-on-windows">USB printers on Windows</a>.</p><h3 id="mesho-prime-isn-t-detected" tabindex="-1">meshO Prime isn&#39;t detected <a class="header-anchor" href="#mesho-prime-isn-t-detected" aria-label="Permalink to &quot;meshO Prime isn&#39;t detected&quot;">​</a></h3><p><strong>There is no COM port to choose.</strong> Manager finds Prime by itself, and the <strong>Devices</strong> page shows <em>Searching for meshO Prime</em> until it does. If it stays there:</p><ul><li><strong>Plug Prime into the computer running Manager</strong>, not into a download laptop. Prime is read by the server; only SportIdent readers plug into other computers. See <a href="./../download-and-install/#one-exception-mesho-prime-must-plug-into-the-server">meshO Prime must plug into the server</a>.</li><li><strong>Try another cable and USB port.</strong> A charge-only USB cable powers Prime without carrying data.</li><li><strong>Open Diagnostics</strong> from the dashboard&#39;s <strong>Field Units</strong> card, which shows what Manager can see on the computer&#39;s ports.</li></ul><p>If Prime was connected and the Devices page and Field Units card have gone back to <em>Searching</em>, the cable was pulled or the connection reset. Reconnect it and Manager picks Prime up again. Punches Prime stored meanwhile can be fetched with <strong>Resend stored punches</strong> (see below).</p><h3 id="prime-is-connected-but-no-radio-punches-arrive" tabindex="-1">Prime is connected, but no radio punches arrive <a class="header-anchor" href="#prime-is-connected-but-no-radio-punches-arrive" aria-label="Permalink to &quot;Prime is connected, but no radio punches arrive&quot;">​</a></h3><ul><li><strong>Is radio for this event switched on?</strong> <strong>Event details → Radio Controls → meshO Prime</strong>. It&#39;s set per event.</li><li><strong>Is the event live?</strong> Punches are recorded only while the event is running. After Manager restarts, a live event comes back <strong>interrupted</strong>, and nothing is recorded until someone clicks <strong>Resume event</strong>.</li><li><strong>Are the controls reporting?</strong> The <strong>Field Units</strong> card on the dashboard shows a dot per control: green reporting, orange quiet for a few minutes, red silent, grey never heard from. A red or grey control may be switched off, out of range, or flat; check its battery on the <strong>Radios</strong> page.</li><li><strong>Did Prime hold punches before the event started?</strong> <strong>Radio punches → Actions → Resend stored punches</strong> asks Prime for everything in its memory; anything Manager already has is ignored.</li></ul><p>See <a href="./../running-the-event/connecting-prime-and-radios">Connecting meshO Prime and radios</a> and <a href="./../running-the-event/radio-punches#recovering-missed-punches">Recovering missed punches</a>.</p><h3 id="a-sportident-reader-isn-t-detected-windows-linux" tabindex="-1">A SportIdent reader isn&#39;t detected (Windows, Linux) <a class="header-anchor" href="#a-sportident-reader-isn-t-detected-windows-linux" aria-label="Permalink to &quot;A SportIdent reader isn&#39;t detected (Windows, Linux)&quot;">​</a></h3><ul><li><strong>Use a browser with Web Serial:</strong> Chrome or Edge, or Firefox 151 or later. Safari doesn&#39;t have it.</li><li><strong>On a computer other than the server, use the secure link.</strong> Web Serial only works on a secure page: <code>localhost</code> on the server itself, or the <strong>https</strong> link on any other computer. See <a href="./https-and-certificates">HTTPS and certificates</a>.</li><li><strong>&quot;The card reader is busy with station memory&quot;.</strong> One reader serves both card download and station memory. Wait for the station-memory read to finish, or disconnect it there. See <a href="./../running-the-event/station-memory">Station memory</a>.</li></ul><h2 id="reaching-the-server" tabindex="-1">Reaching the server <a class="header-anchor" href="#reaching-the-server" aria-label="Permalink to &quot;Reaching the server&quot;">​</a></h2><h3 id="a-laptop-can-t-find-the-server-by-name-—-dns-probe-finished-nxdomain" tabindex="-1">A laptop can&#39;t find the server by name — <code>DNS_PROBE_FINISHED_NXDOMAIN</code> <a class="header-anchor" href="#a-laptop-can-t-find-the-server-by-name-—-dns-probe-finished-nxdomain" aria-label="Permalink to &quot;A laptop can&#39;t find the server by name — `DNS_PROBE_FINISHED_NXDOMAIN`&quot;">​</a></h3><p>Chrome shows <strong>&quot;This site can&#39;t be reached&quot;</strong> with <code>DNS_PROBE_FINISHED_NXDOMAIN</code> for the name-based access link, while the same address opens fine in Safari, Firefox or on a phone. Chrome uses its own DNS resolver and frequently won&#39;t resolve the server&#39;s computer name, so it asks the router instead — which has no record for it.</p><p>Use the link tagged <strong>IP</strong> in <strong>Settings → Server → Access links</strong> on that laptop. This hits download and station-backup machines hardest, because those are the ones typically running Chrome for Web Serial. To use a name on them anyway, give the server a DHCP reservation and host name on the venue router, or run Firefox 151+ there — it also has Web Serial and looks names up through the operating system. Full detail: <a href="./server-addresses">Reaching the server: name or IP</a>.</p><blockquote><p>If <strong>neither</strong> the name nor the IP works from another device, it isn&#39;t this — check <strong>Allow access from other devices on the network</strong> in <strong>Settings → Server</strong>, then the server machine&#39;s firewall.</p></blockquote><h2 id="saving" tabindex="-1">Saving <a class="header-anchor" href="#saving" aria-label="Permalink to &quot;Saving&quot;">​</a></h2><h3 id="a-full-screen-this-event-can-t-be-saved-message-appears" tabindex="-1">A full-screen &quot;This event can&#39;t be saved&quot; message appears <a class="header-anchor" href="#a-full-screen-this-event-can-t-be-saved-message-appears" aria-label="Permalink to &quot;A full-screen &quot;This event can&#39;t be saved&quot; message appears&quot;">​</a></h3><p>meshO Manager can no longer write to the event&#39;s folder on this computer. The screen is paused behind the message until it can, and the message can&#39;t be dismissed — the only ways out are fixing the folder and pressing <strong>Retry</strong>, or closing Manager. Card downloads and radio punches are still taken while it is up.</p><p><strong>Your changes are not lost.</strong> The changes made since the problem started — card downloads, radio punches, edits, and the audit trail&#39;s record of them — are held in memory, and a second copy is saved outside the event folder. The message shows where. If you close Manager before fixing the problem, those changes are applied automatically the next time you open the event.</p><p>The message shows the <strong>event folder</strong>, which parts of the event can&#39;t be saved (the competitor and punch data, the audit trail, or individual files such as the class list) and the system&#39;s own reason for each. To fix it:</p><ol><li><strong>Check the folder isn&#39;t read-only.</strong> On Windows, right-click the folder → <strong>Properties</strong> and look at the <strong>Security</strong> tab: your user needs <strong>Modify</strong> or <strong>Full control</strong>. The <strong>Read-only</strong> tick box on the General tab is not a reliable guide for folders — Windows shows it filled in even when the folder is writable — so clearing it usually changes nothing.</li><li><strong>Move the event out of a synced folder.</strong> If the folder is inside OneDrive, Dropbox or Google Drive, pause syncing, or move the event to a plain local folder such as <code>C:\\meshO</code>. Sync clients can lock a database file while they upload it.</li><li><strong>Check antivirus and ransomware protection.</strong> On Windows, <strong>Windows Security → Virus &amp; threat protection → Ransomware protection → Controlled folder access</strong> can silently block Manager from writing. Allow meshO Manager through it, or turn it off for the day.</li><li><strong>Check the disk isn&#39;t full</strong> and that nothing else — a second copy of Manager, a backup tool — has the event&#39;s <code>meshO.db</code> file (or <code>AuditTrail\\AuditTrail.db</code>) open.</li></ol><p>Then press <strong>Retry</strong>. Manager tries again to write everything it was holding back — reopening the event&#39;s database and audit trail and rewriting each file — and checks that each write really landed. If it still can&#39;t write, the message stays up with the new reason and how many attempts have failed; fix that and retry again. The message disappears by itself once everything is saved.</p><p>If the message says it could <strong>not save a second copy</strong> either, don&#39;t close Manager until the problem is fixed — the held-back changes then exist only in memory.</p><p>If the message says the event&#39;s database <strong>failed its integrity check</strong>, retrying won&#39;t fix it. Keep Manager open and contact meshO support.</p><p>If the message says the <strong>details could not be loaded</strong>, the problem is still there and <strong>Retry</strong> still works; the details come back once Manager answers again.</p><h2 id="event-data" tabindex="-1">Event data <a class="header-anchor" href="#event-data" aria-label="Permalink to &quot;Event data&quot;">​</a></h2><h3 id="an-event-isn-t-in-the-events-list" tabindex="-1">An event isn&#39;t in the Events list <a class="header-anchor" href="#an-event-isn-t-in-the-events-list" aria-label="Permalink to &quot;An event isn&#39;t in the Events list&quot;">​</a></h3><ul><li><strong>Look on the History tab.</strong> <strong>Upcoming</strong> holds the running event, and events dated today or later that haven&#39;t been finished. Finished events, and every event dated before today, are on <strong>History</strong>, including one that was set up and never run.</li><li><strong>It&#39;s part of a multi-stage event.</strong> A carnival&#39;s days are listed under its group header; open the group.</li><li><strong>It&#39;s on another computer.</strong> Events live on the computer where they were created or restored. To move one, see <a href="./../event-setup/moving-an-event">Moving an event to another computer</a>.</li></ul><h3 id="a-re-import-added-a-second-copy-of-some-competitors" tabindex="-1">A re-import added a second copy of some competitors <a class="header-anchor" href="#a-re-import-added-a-second-copy-of-some-competitors" aria-label="Permalink to &quot;A re-import added a second copy of some competitors&quot;">​</a></h3><p>A re-imported entry list recognises the competitors it already has by their <strong>registration number</strong> (such as their Eventor ID), then their <strong>card number</strong>. It matches on name only when the entry has neither. So a runner typed in by hand at the desk, and then sent in the entry file with an Eventor ID and a different card, arrives as a second competitor.</p><p>Keep the copy that has their card download and result, and delete the other one. If both have something on them, move the download to the right one first from <a href="./../running-the-event/card-download">Card downloads</a>. See <a href="./../event-setup/import-event-data#re-importing">Re-importing</a>.</p><h3 id="an-imported-file-is-missing-people-or-manager-asks-about-removing-some" tabindex="-1">An imported file is missing people, or Manager asks about removing some <a class="header-anchor" href="#an-imported-file-is-missing-people-or-manager-asks-about-removing-some" aria-label="Permalink to &quot;An imported file is missing people, or Manager asks about removing some&quot;">​</a></h3><p>Manager never deletes on an import unless you ask it to. If the file doesn&#39;t list competitors the event already has, it stops and asks whether the file is the complete list. See <a href="./../event-setup/import-event-data#when-a-file-is-missing-competitors-or-classes-you-already-have">When a file is missing competitors or classes you already have</a>.</p><h2 id="during-the-event" tabindex="-1">During the event <a class="header-anchor" href="#during-the-event" aria-label="Permalink to &quot;During the event&quot;">​</a></h2><h3 id="punches-arrive-but-don-t-land-on-a-competitor" tabindex="-1">Punches arrive, but don&#39;t land on a competitor <a class="header-anchor" href="#punches-arrive-but-don-t-land-on-a-competitor" aria-label="Permalink to &quot;Punches arrive, but don&#39;t land on a competitor&quot;">​</a></h3><p>On <strong>Radio punches</strong>, the runner&#39;s name shows <strong>Unknown</strong>: nobody in the event holds that card number. Either the card number on their entry is wrong (they&#39;re carrying a different or hire card), or they aren&#39;t entered. Click <strong>Unknown</strong> to add a competitor for that card, or correct the card number on their entry; their earlier punches are then matched to them. See <a href="./../running-the-event/radio-punches#unknown-cards">Unknown cards</a>.</p><h3 id="a-control-s-times-are-all-out-by-the-same-amount" tabindex="-1">A control&#39;s times are all out by the same amount <a class="header-anchor" href="#a-control-s-times-are-all-out-by-the-same-amount" aria-label="Permalink to &quot;A control&#39;s times are all out by the same amount&quot;">​</a></h3><p>The unit&#39;s clock was wrong. Set a <strong>Time Offset</strong> on the control, and every punch from it is corrected, earlier ones included. See <a href="./../event-setup/controls-and-radio-controls#time-offset">Time Offset</a>.</p><h3 id="a-tv-screen-is-blank-or-shows-the-wrong-thing" tabindex="-1">A TV screen is blank, or shows the wrong thing <a class="header-anchor" href="#a-tv-screen-is-blank-or-shows-the-wrong-thing" aria-label="Permalink to &quot;A TV screen is blank, or shows the wrong thing&quot;">​</a></h3><ul><li><strong>Check its link.</strong> A screen&#39;s link includes the server&#39;s address and the event&#39;s id. A link from another event, or one taken from a different server, shows nothing for this one. Open it again from the event&#39;s <strong>Screens</strong> page. See <a href="./../screens/tv-screens#opening-each-screen-on-its-tv">Opening each screen on its TV</a>.</li><li><strong>Results held back on purpose.</strong> A class under <a href="./../event-setup/results-quarantine">results quarantine</a> shows its start list but not its results until its release time.</li><li><strong>The TV lost the network.</strong> Screens catch up by themselves when they reconnect. If one doesn&#39;t, reload the page on the TV.</li></ul><h3 id="there-s-an-alert-i-don-t-understand" tabindex="-1">There&#39;s an alert I don&#39;t understand <a class="header-anchor" href="#there-s-an-alert-i-don-t-understand" aria-label="Permalink to &quot;There&#39;s an alert I don&#39;t understand&quot;">​</a></h3><p>Alerts collect in the <strong>Alerts</strong> panel at the right of the manager screens, and the alert icon flashes while there&#39;s one you haven&#39;t seen. Each alert says what happened and, where there&#39;s something to do, what that is: a low battery, a lost connection, an external backup drive that&#39;s missing. Many withdraw themselves when the problem clears.</p><p><strong>Dismissing</strong> an alert removes it from the panel and stops the icon flashing for the rest of the event. The message stays in the <strong>Messages</strong> panel. If the problem comes back, for example a battery drops further, a new alert appears.</p><h3 id="a-result-looks-wrong" tabindex="-1">A result looks wrong <a class="header-anchor" href="#a-result-looks-wrong" aria-label="Permalink to &quot;A result looks wrong&quot;">​</a></h3><p>That&#39;s usually a status, a punch or a start time to correct on the competitor. See <a href="./../running-the-event/resolving-issues">Resolving issues on the day</a> and <a href="./status-and-race-time">Status and race time rules</a>.</p><h3 id="a-runner-marked-dns-ran-after-all-and-still-shows-dns" tabindex="-1">A runner marked DNS ran after all, and still shows DNS <a class="header-anchor" href="#a-runner-marked-dns-ran-after-all-and-still-shows-dns" aria-label="Permalink to &quot;A runner marked DNS ran after all, and still shows DNS&quot;">​</a></h3><p>A DNS you set is kept through every later card download. Open them, go to <strong>Result</strong>, and press <strong>Auto</strong> beside the status. See <a href="./../running-the-event/late-entries#marked-dns-then-they-turn-up">Marked DNS, then they turn up</a>.</p><h2 id="logs-and-getting-help" tabindex="-1">Logs and getting help <a class="header-anchor" href="#logs-and-getting-help" aria-label="Permalink to &quot;Logs and getting help&quot;">​</a></h2><h3 id="where-the-logs-are" tabindex="-1">Where the logs are <a class="header-anchor" href="#where-the-logs-are" aria-label="Permalink to &quot;Where the logs are&quot;">​</a></h3><p>Manager writes a log file each day, named <code>log-</code> and the date, in a <code>logs</code> folder:</p><table tabindex="0"><thead><tr><th>Computer</th><th>Logs folder</th></tr></thead><tbody><tr><td>Windows</td><td><code>%LOCALAPPDATA%\\meshO Manager\\logs</code> (paste it into Explorer&#39;s address bar)</td></tr><tr><td>macOS</td><td><code>~/Library/Application Support/meshO Manager/logs</code></td></tr><tr><td>Linux</td><td><code>~/.local/share/meshO Manager/logs</code></td></tr></tbody></table><p>On a Mac or Linux, the tray&#39;s <strong>Show Files</strong> opens the folder that holds <code>logs</code>. On Windows, it opens the events folder, which is somewhere else. <strong>Settings → Logging</strong> sets how much detail goes into the log; leave it alone unless support asks.</p><h3 id="what-to-send-with-a-support-request" tabindex="-1">What to send with a support request <a class="header-anchor" href="#what-to-send-with-a-support-request" aria-label="Permalink to &quot;What to send with a support request&quot;">​</a></h3><ol><li><strong>What happened, and roughly when</strong>: the time helps find it in the log.</li><li><strong>The version</strong>, from <strong>About</strong> in the tray or menu bar.</li><li><strong>That day&#39;s log file</strong> (above).</li><li><strong>A backup of the event</strong>, if the problem is about an event: <strong>Backup event → Download</strong> on its card. It includes the event&#39;s audit trail, card downloads and radio data, which is usually what&#39;s needed to see what happened. It also holds competitors&#39; details and the liveresultat password, so send it privately, never post it publicly. See <a href="./backup-and-restore">Backup and restore</a>.</li></ol><h3 id="a-damaged-event-or-one-that-won-t-open" tabindex="-1">A damaged event, or one that won&#39;t open <a class="header-anchor" href="#a-damaged-event-or-one-that-won-t-open" aria-label="Permalink to &quot;A damaged event, or one that won&#39;t open&quot;">​</a></h3><p>See <a href="./backup-and-restore#repairing-a-damaged-event">Repairing a damaged event</a>.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./../running-the-event/resolving-issues">Resolving issues on the day</a></li><li><a href="./server-addresses">Reaching the server: name or IP</a></li><li><a href="./../running-the-event/connecting-prime-and-radios">Connecting meshO Prime and radios</a></li><li><a href="./sportident-usb-on-macos">SportIdent USB stations on macOS</a></li><li><a href="./usb-printer-on-windows">USB printers on Windows</a></li><li><a href="./../download-and-install/">Installing meshO Manager</a></li></ul>',77)])])}const u=t(o,[["render",s]]);export{p as __pageData,u as default};
